const test = require('node:test')
const assert = require('node:assert/strict')
const { countedText, check } = require('./check.js')

test('countedText: drops attribution, comments and footers', () => {
  const body = [
    '<!-- claude-projects-attribution: {"github_login":"x"} -->',
    '_Requested by **x** · [project thread](https://claude.ai/x)_',
    '',
    '## Summary',
    '- Does a thing.',
    '',
    '🤖 Generated with [Claude Code](https://claude.com/claude-code)',
    '',
    'https://claude.ai/code/session_123',
    '---',
    '_Generated by [Claude Code](https://claude.ai/code)_',
    '<!-- codesmith:footer -->',
    '<a href="x">Autofix</a>',
    '<!-- /codesmith:footer -->'
  ].join('\r\n')
  assert.equal(countedText(body), '## Summary\n- Does a thing.')
})

test('countedText: drops Cursor Cloud Agent PR footer without dropping user HTML', () => {
  const cursorFooter = '<div><a href="https://cursor.com/agents/bc-a62c528a-e7c9-4694-a5c4-a6a7cd0e5ea8?cursor_ref=pr_footer&cursor_cta=open_in_web"><picture><source media="(prefers-color-scheme: dark)" srcset="https://cursor.com/assets/images/open-in-web-dark.png"><source media="(prefers-color-scheme: light)" srcset="https://cursor.com/assets/images/open-in-web-light.png"><img alt="Open in Web" width="114" height="28" src="https://cursor.com/assets/images/open-in-web-dark.png"></picture></a>&nbsp;<a href="https://cursor.com/background-agent?bcId=bc-a62c528a-e7c9-4694-a5c4-a6a7cd0e5ea8&cursor_ref=pr_footer&cursor_cta=open_in_cursor"><picture><source media="(prefers-color-scheme: dark)" srcset="https://cursor.com/assets/images/open-in-cursor-dark.png"><source media="(prefers-color-scheme: light)" srcset="https://cursor.com/assets/images/open-in-cursor-light.png"><img alt="Open in Cursor" width="131" height="28" src="https://cursor.com/assets/images/open-in-cursor-dark.png"></picture></a>&nbsp;</div>'
  const body = [
    '<div>User HTML</div>',
    '<div><a href="https://cursor.com/docs">Cursor docs</a></div>',
    '',
    '## Summary',
    '- Does a thing.',
    '',
    '---',
    cursorFooter
  ].join('\r\n')
  assert.equal(countedText(body), '<div>User HTML</div>\n<div><a href="https://cursor.com/docs">Cursor docs</a></div>\n\n## Summary\n- Does a thing.')
})

test('countedText: counts every section', () => {
  const body = '## Summary\nkept\n## Decisions\n### Precedent\n| a | b |\n## Reviewer notes\nkept too'
  assert.equal(countedText(body), body)
})

test('countedText: handles a missing body', () => {
  assert.equal(countedText(null), '')
})

function run (body, { fetchFails = false, status = 404 } = {}) {
  const out = { info: [], warning: [], failed: [] }
  const core = {
    info: (m) => out.info.push(m),
    warning: (m) => out.warning.push(m),
    setFailed: (m) => out.failed.push(m)
  }
  const github = {
    rest: {
      pulls: {
        get: async () => {
          if (fetchFails) throw Object.assign(new Error('failed'), { status })
          return { data: { body } }
        }
      }
    }
  }
  const context = { repo: { owner: 'o', repo: 'r' }, payload: { pull_request: { number: 1, body: fetchFails ? body : 'stale' } } }
  return check({ github, context, core, limit: 10 }).then(() => out)
}

test('check: passes at the limit and fails over it, using the live body', async () => {
  assert.deepEqual((await run('x'.repeat(10))).failed, [])
  const out = await run('x'.repeat(11))
  assert.match(out.failed[0], /11 characters.*limit is 10.*re-run this job/)
})

test('check: counts characters, not UTF-16 units', async () => {
  assert.deepEqual((await run('🤖'.repeat(10))).failed, [])
})

test('check: falls back to the event body and says to push', async () => {
  const out = await run('x'.repeat(11), { fetchFails: true })
  assert.match(out.warning[0], /Grant pull-requests: read/)
  assert.match(out.failed[0], /push a commit to re-check/)
})

test('check: skips Mikado reference PRs', async () => {
  const out = await run('<!-- a -->\n> **Reference PR — do not merge.**\n' + 'x'.repeat(50))
  assert.deepEqual(out.failed, [])
})

test('check: only suggests the permission when access is denied', async () => {
  const out = await run('x', { fetchFails: true, status: 502 })
  assert.doesNotMatch(out.warning[0], /Grant/)
})
